  for epoch: W.U64
  for encoded: Result<&2, &2, C.CalendarError, W.U64>
  {Laws.encodedSame(epoch, encoded) == I.same(epoch, encoded) : Bool}

def same_projection(epoch, encoded):
  match encoded:
    case Fail{_}: {==}
    case Done{_}: {==}

law checked_result:
  for +epoch: W.U64
  for +value: C.CivilTime
  {Laws.reconstructs(epoch, I.checked(epoch, value)) == True{} : Bool}

def checked_result(epoch, value):
  verified_result(epoch, value, I.same(epoch, C.toEpochMilliseconds(value)), same_projection(epoch, C.toEpochMilliseconds(value)))

law divided_result:
  for +epoch: W.U64
  for +result: Maybe<&2, W.Division>
  {Laws.reconstructs(epoch, I.divided(epoch, result)) == True{} : Bool}

def divided_result(epoch, result):
  match result:
    case Some{W.Division{W.U64{0, +day}, W.U64{0, millis}}}: checked_result(epoch, I.inYear(day, millis, I.year(14n, day, 0, 9999)))
    case _: {==}

law ranged_result:
  for +epoch: W.U64
  for shifted: W.U64
  for order: Cmp
  {Laws.reconstructs(epoch, I.ranged(epoch, shifted, order)) == True{} : Bool}

def ranged_result(epoch, shifted, order):
  match order:
    case LT{}: divided_result(epoch, W.divide(shifted, W.fromU32(86400000)))
    case _: {==}

def Laws.successful_inverse_reconstructs_original_epoch(epoch):
  +shifted = W.add(epoch, I.epochOffset())
  ranged_result(epoch, shifted, W.compare(shifted, I.extent()))

